    if (clockInMinutes <= officeMinutes) return {
        text: "On Time",
        color: "text-green-500"
    };
    if (clockInMinutes <= deadlineMinutes) return {
        text: "Within Grace",
        color: "text-yellow-500"
    };
    const lateBy = clockInMinutes - officeMinutes;
